const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { Given, When, Then } = require('@cucumber/cucumber');
const Ajv = require('ajv/dist/2020');

const STORAGE_KEY = 'todos-vanillajs';
const ROOT = path.resolve(__dirname, '..', '..');

const titles = (list) =>
  list
    .split(',')
    .map((t) => t.trim())
    .filter((t) => t.length > 0);

const text = (el) => (el ? el.textContent.replace(/\s+/g, ' ').trim() : '');

function hidden(el) {
  if (!el) return true;
  if (el.hasAttribute('hidden')) return true;
  if (el.classList.contains('hidden')) return true;
  const display = el.style && el.style.display;
  return display === 'none';
}

function items(world) {
  return Array.from(world.document.querySelectorAll('.todo-list li')).filter((li) => !hidden(li));
}

function itemTitles(world) {
  return items(world).map((li) => text(li.querySelector('label')));
}

function itemFor(world, title) {
  const li = items(world).find((el) => text(el.querySelector('label')) === title);
  assert.ok(li, `no todo titled "${title}" in the list: ${JSON.stringify(itemTitles(world))}`);
  return li;
}

const newTodoInput = (world) => world.document.querySelector('.new-todo');
const toggleAll = (world) => world.document.querySelector('.toggle-all');
const clearCompleted = (world) => world.document.querySelector('.clear-completed');
const counter = (world) => world.document.querySelector('.todo-count');

function stored(world) {
  const raw = world.localStorage.getItem(STORAGE_KEY);
  assert.ok(raw !== null && raw !== undefined, `local storage under "${STORAGE_KEY}" holds nothing`);
  return JSON.parse(raw);
}

function fire(world, el, type, init = {}) {
  el.dispatchEvent(new world.window.Event(type, { bubbles: true, ...init }));
}

function key(world, el, name, code) {
  const event = new world.window.KeyboardEvent('keydown', {
    key: name,
    code: name,
    bubbles: true,
    cancelable: true,
  });
  for (const prop of ['keyCode', 'which']) {
    if (event[prop] !== code) Object.defineProperty(event, prop, { value: code, configurable: true });
  }
  el.dispatchEvent(event);
  el.dispatchEvent(
    new world.window.KeyboardEvent('keyup', { key: name, code: name, bubbles: true, cancelable: true }),
  );
}

function setValue(world, el, value) {
  el.value = value;
  fire(world, el, 'input');
}

function typeNewTodo(world, title) {
  const input = newTodoInput(world);
  assert.ok(input, 'the page has no .new-todo input');
  input.focus();
  setValue(world, input, title);
  key(world, input, 'Enter', 13);
}

function setChecked(world, checkbox, wanted) {
  assert.ok(checkbox, 'no checkbox to click');
  if (checkbox.checked !== wanted) checkbox.click();
  assert.equal(checkbox.checked, wanted, 'the checkbox did not take the clicked state');
}

const seedItems = (list, completed) =>
  titles(list).map((title, index) => ({ id: `seed-${index + 1}`, title, completed }));

// --- Given: browser state -------------------------------------------------

Given('the browser has no stored todos', function () {
  this.seed = [];
});

Given('the browser has the stored todo {string}', async function (title) {
  this.seed = seedItems(title, false);
  await this.reload();
});

Given('the browser has the stored todos {string}', async function (list) {
  this.seed = seedItems(list, false);
  await this.reload();
});

Given('the browser has the stored completed todo {string}', async function (title) {
  this.seed = seedItems(title, true);
  await this.reload();
});

Given('the browser location hash is {string}', function (hash) {
  this.seedHash = hash;
});

// --- Given / When: loading ------------------------------------------------

When('the app loads', async function () {
  await this.reload();
});

Given('the app is loaded', async function () {
  await this.reload();
});

Given('the app is loaded with the todos {string}', async function (list) {
  await this.reload();
  for (const title of titles(list)) typeNewTodo(this, title);
});

Given('the app is loaded with the completed todo {string}', async function (title) {
  await this.reload();
  for (const t of titles(title)) typeNewTodo(this, t);
  for (const t of titles(title)) setChecked(this, itemFor(this, t).querySelector('.toggle'), true);
});

Given('the app is loaded with the completed todos {string}', async function (list) {
  await this.reload();
  for (const t of titles(list)) typeNewTodo(this, t);
  for (const t of titles(list)) setChecked(this, itemFor(this, t).querySelector('.toggle'), true);
});

// --- When: the user acts --------------------------------------------------

When('the user types {string} into the new todo input and presses Enter', function (title) {
  typeNewTodo(this, title);
});

When('the user adds the todo {string}', function (title) {
  typeNewTodo(this, title);
});

When('the user removes the todo {string}', function (title) {
  itemFor(this, title).querySelector('.destroy').click();
});

function check(world, title, wanted) {
  setChecked(world, itemFor(world, title).querySelector('.toggle'), wanted);
}

Given('the todo {string} is checked', function (title) {
  check(this, title, true);
});

When('the user checks the todo {string}', function (title) {
  check(this, title, true);
});

When('the user unchecks the todo {string}', function (title) {
  check(this, title, false);
});

When('the user checks the todos {string}', function (list) {
  for (const title of titles(list)) check(this, title, true);
});

When('the user checks the mark all as complete checkbox', function () {
  setChecked(this, toggleAll(this), true);
});

When('the user unchecks the mark all as complete checkbox', function () {
  setChecked(this, toggleAll(this), false);
});

When('the user clicks the clear completed button', function () {
  const button = clearCompleted(this);
  assert.ok(button, 'the page has no .clear-completed button');
  button.click();
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

// --- Editing --------------------------------------------------------------

function startEditing(world, title) {
  const label = itemFor(world, title).querySelector('label');
  label.dispatchEvent(new world.window.Event('dblclick', { bubbles: true, cancelable: true }));
}

function editInput(world) {
  const li = Array.from(world.document.querySelectorAll('.todo-list li')).find((el) =>
    el.classList.contains('editing'),
  );
  assert.ok(li, 'no todo is in editing mode');
  const input = li.querySelector('.edit');
  assert.ok(input, 'the editing todo has no .edit input');
  return input;
}

When('the user double-clicks the label of the todo {string}', function (title) {
  startEditing(this, title);
});

Given('the user is editing the todo {string}', function (title) {
  startEditing(this, title);
});

When('the user types {string} into the edit input and presses Enter', function (value) {
  const input = editInput(this);
  setValue(this, input, value);
  key(this, input, 'Enter', 13);
});

When('the user types {string} into the edit input and presses Escape', function (value) {
  const input = editInput(this);
  setValue(this, input, value);
  key(this, input, 'Escape', 27);
});

When('the user types {string} into the edit input and blurs it', function (value) {
  const input = editInput(this);
  setValue(this, input, value);
  if (this.document.activeElement === input) input.blur();
  else input.dispatchEvent(new this.window.Event('blur'));
});

Then('the todo {string} is in editing mode', function (title) {
  assert.ok(
    itemFor(this, title).classList.contains('editing'),
    `the todo "${title}" does not carry the editing class`,
  );
});

Then('no todo is in editing mode', function () {
  const editing = Array.from(this.document.querySelectorAll('.todo-list li')).filter((li) =>
