Then('the mark all as complete checkbox is unchecked', function () {
  assert.equal(toggleAll(this).checked, false);
});

Then('the clear completed button is hidden', function () {
  assert.ok(hidden(clearCompleted(this)), 'the clear completed button is visible');
});

Then('the clear completed button is visible', function () {
  assert.equal(hidden(clearCompleted(this)), false, 'the clear completed button is hidden');
